var MATH_FUNCS={ sin:Math.sin, cos:Math.cos, tan:Math.tan, asin:Math.asin, acos:Math.acos, atan:Math.atan,
  sinh:Math.sinh, cosh:Math.cosh, tanh:Math.tanh, sqrt:Math.sqrt, cbrt:Math.cbrt,
  abs:Math.abs, floor:Math.floor, ceil:Math.ceil, round:Math.round, trunc:Math.trunc,
  exp:Math.exp, log:Math.log, ln:Math.log, log10:Math.log10, log2:Math.log2,
  sign:Math.sign, pow:Math.pow, min:Math.min, max:Math.max };
var MATH_CONSTS={ pi:Math.PI, e:Math.E, tau:2*Math.PI, phi:(1+Math.sqrt(5))/2 };
var MATH_PREC={ '+':1, '-':1, '*':2, '/':2, '%':2, '^':3, 'u':4 };
var MATH_RIGHT={ '^':true, 'u':true };

function tokenize(expr){
  var s=String(expr).toLowerCase().replace(/\s+/g,'');
  var tokens=[], i=0;
  while(i<s.length){
    var c=s[i];
    if(/[0-9.]/.test(c)){
      var num=''; while(i<s.length && /[0-9.]/.test(s[i])){ num+=s[i]; i++; }
      tokens.push({t:'num', v:parseFloat(num)});
    } else if(/[a-z]/.test(c)){
      var name=''; while(i<s.length && /[a-z]/.test(s[i])){ name+=s[i]; i++; }
      tokens.push({t:'name', v:name});
    } else if('+-*/^()%'.indexOf(c)>=0){
      tokens.push({t:'op', v:c}); i++;
    } else { throw new Error('非法字符: '+c); }
  }
  return tokens;
}
function toRPN(tokens){
  var prev='start', proc=[];
  for(var i=0;i<tokens.length;i++){
    var tk=tokens[i];
    if(tk.t==='op' && tk.v==='-'){
      if(prev==='start'||prev==='op'||prev==='('){ proc.push({t:'op', v:'u'}); prev='op'; continue; }
      proc.push(tk); prev='op'; continue;
    }
    if(tk.t==='op' && tk.v==='+'){
      if(prev==='start'||prev==='op'||prev==='('){ prev=(prev==='(')?'(': 'op'; continue; }
      proc.push(tk); prev='op'; continue;
    }
    proc.push(tk);
    if(tk.t==='op') prev='op';
    else if(tk.t==='num') prev='num';
    else if(tk.t==='name') prev='name';
  }
  var out=[], ops=[];
  for(var j=0;j<proc.length;j++){
    var t=proc[j];
    if(t.t==='num') out.push(t);
    else if(t.t==='name'){
      if(MATH_CONSTS[t.v]!==undefined) out.push({t:'num', v:MATH_CONSTS[t.v]});
      else ops.push({t:'func', v:t.v});
    }
    else if(t.t==='op' && t.v==='(') ops.push(t);
    else if(t.t==='op' && t.v===')'){
      while(ops.length && ops[ops.length-1].v!=='(') out.push(ops.pop());
      if(ops.length && ops[ops.length-1].v==='(') ops.pop();
      if(ops.length && ops[ops.length-1].t==='func') out.push(ops.pop());
    }
    else if(t.t==='op'){
      var o1=t.v;
      while(ops.length){
        var top=ops[ops.length-1];
        if(top.t==='op' && top.v!=='(' && ( (MATH_PREC[o1]<MATH_PREC[top.v]) || (MATH_PREC[o1]===MATH_PREC[top.v] && !MATH_RIGHT[o1]) )) out.push(ops.pop());
        else break;
      }
      ops.push({t:'op', v:o1});
    }
  }
  while(ops.length) out.push(ops.pop());
  return out;
}
function evalRPN(rpn){
  var st=[];
  for(var i=0;i<rpn.length;i++){
    var tk=rpn[i];
    if(tk.t==='num') st.push(tk.v);
    else if(tk.t==='func'){
      if(st.length<1) throw new Error('函数 '+tk.v+' 缺少参数');
      var a=st.pop();
      if(MATH_FUNCS[tk.v]===undefined) throw new Error('未知函数 '+tk.v);
      st.push(MATH_FUNCS[tk.v](a));
    }
    else if(tk.t==='op'){
      if(tk.v==='u'){ if(!st.length) throw new Error('缺少操作数'); st.push(-st.pop()); continue; }
      if(st.length<2) throw new Error('缺少操作数');
      var b=st.pop(), x=st.pop();
      if(tk.v==='+') st.push(x+b);
      else if(tk.v==='-') st.push(x-b);
      else if(tk.v==='*') st.push(x*b);
      else if(tk.v==='/'){ if(b===0) throw new Error('除以零'); st.push(x/b); }
      else if(tk.v==='%'){ if(b===0) throw new Error('模零'); st.push(x%b); }
      else if(tk.v==='^') st.push(Math.pow(x,b));
    }
  }
  if(st.length!==1) throw new Error('表达式无效');
  return st[0];
}
function evaluate(expr){ return evalRPN(toRPN(tokenize(expr))); }
function fmt(n){
  if(!isFinite(n)) return String(n);
  if(Math.abs(n-Math.round(n))<1e-10) return String(Math.round(n));
  return String(Math.round(n*1e10)/1e10);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tokenize:tokenize, toRPN:toRPN, evalRPN:evalRPN, evaluate:evaluate, fmt:fmt };
}
if (typeof window !== 'undefined') {
  window.MathForgePure = { tokenize:tokenize, toRPN:toRPN, evalRPN:evalRPN, evaluate:evaluate, fmt:fmt };
}
